INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M820-09-D1', 'oberschwellig_code = if(estimated_engineering_fee >= eu_threshold_value, 1, 0)', ARRAY['estimated_engineering_fee','eu_threshold_value']::text[], 'oberschwellig_code', NULL, '§ 8.6; Anhang B.2.3 (§ 106 GWB)', 'Plan 3: 1 wenn der geschätzte Netto-Gesamtwert den EU-Schwellenwert erreicht oder übersteigt (§ 8.6 "Erreicht oder übersteigt"), sonst 0; Zwilling zu oberschwellig_check / threshold_status — REQ-07 / REQ-08 STAGED (m820_1-G-3).', 'imported_unverified', 'Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen. Liegt er darunter, hat der Auftraggeber ein Suchverfahren durchzuführen oder er kann in zugelassenen Ausnahmefällen eine Direktvergabe (siehe 8.8) vornehmen. — In § 106 GWB ist festgelegt, dass das GWB und in Folge die VgV nur gelten, soweit der geschätzte Auftragswert die EU-Schwellenwerte erreicht oder überschreitet.'
